insert into public.portfolio_news (seed_key, title, position, published, date_label, date_value, body) values ('news-nexus-conference', 'As President of the Conference Committee, I was part of the organizing team, who organized the Nexus 2.0 Energy Policy and Innovation Conference, bringing together over 500 students, 100 volunteers, and 10 energy leaders and dignitaries. We received sponsorship funding from Heirs Energies and other', 9, true, 'Jul 2025', '2025-07', '{"version":1,"blocks":[{"type":"paragraph","children":[{"text":"As President of the Conference Committee, I was part of the organizing team, who organized the Nexus 2.0 Energy Policy and Innovation Conference, bringing together over 500 students, 100 volunteers, and 10 energy leaders and dignitaries. We received sponsorship funding from Heirs Energies and other technology companies."}]}]}'::jsonb) on conflict (seed_key) do nothing;
