insert into public.portfolio_news (seed_key, title, position, published, date_label, date_value, body) values ('news-bamtoks-valedictorian', 'Graduated as class valedictorian and the highest-achieving student at Bamtoks College.', 19, true, 'Oct 2020', '2020-10', '{"version":1,"blocks":[{"type":"paragraph","children":[{"text":"Graduated as class valedictorian and the highest-achieving student at Bamtoks College."}]}]}'::jsonb) on conflict (seed_key) do nothing;
insert into public.portfolio_projects (seed_key, title, position, published, image_url, image_path, description, categories, credit, date_label, link_url, code_url, demo_url) values ('project-1', 'Computer Vision Research', 0, true, '/images/cv-image.png', '', 'A repository dedicated to my research, implementation and learning about the groundbreaking advancements in Computer Vision. The repository comprises implementation — from scratch — of various prominent Computer Vision architectures, which includes: Vision Transformer, MobileNet, ResNet, EfficientNet, et al. The tasks covered span across image classification, object segmentation, detection and generative models, such as Diffusion models and Generative Adversarial Networks (GANs).', array['Engineering']::text[], 'Silas Osunba', '', 'https://github.com/TolaniSilas/Computer-Vision-Research', 'https://github.com/TolaniSilas/Computer-Vision-Research', '') on conflict (seed_key) do nothing;
insert into public.portfolio_projects (seed_key, title, position, published, image_url, image_path, description, categories, credit, date_label, link_url, code_url, demo_url) values ('project-2', 'Mini GPT', 1, true, '/images/llm-image.png', '', 'Implemented Generative Pretrained Transformer (GPT) models (e.g., GPT-2, GPT-3) for experimental purposes to gain a deeper understanding of the underlying mechanisms of this technology. The model architecture is inspired by a major breakthrough in deep learning: the self-attention mechanism introduced in ''Attention Is All You Need'' by Vaswani et al. It employs a decoder-only Transformer design and incorporates Byte Pair Encoding (BPE) tokenization as its robust text-preprocessing technique.', array['Engineering']::text[], 'Silas Osunba', '', 'https://github.com/TolaniSilas/Mini-GPT', 'https://github.com/TolaniSilas/Mini-GPT', '') on conflict (seed_key) do nothing;
insert into public.portfolio_projects (seed_key, title, position, published, image_url, image_path, description, categories, credit, date_label, link_url, code_url, demo_url) values ('project-3', 'Real-Time Currency Analyst Agent', 2, true, '/images/currency-image.png', '', 'A conversational, financial intelligence AI Agent specialized in analyzing currencies. It fetches real-time exchange rate data and interprets currency relationships at real-time (the current moment). It responsibility is also to provide clear and concise insights for users seeking to understand the relative strength of currencies across various countries or perform instant conversions between different currencies.', array['Engineering']::text[], 'Silas Osunba', '', 'https://github.com/TolaniSilas/genai_works/tree/main/src/currency_analyst_agent', 'https://github.com/TolaniSilas/genai_works/tree/main/src/currency_analyst_agent', '') on conflict (seed_key) do nothing;
insert into public.portfolio_projects (seed_key, title, position, published, image_url, image_path, description, categories, credit, date_label, link_url, code_url, demo_url) values ('project-4', 'Web3 Semantic Search', 3, true, '/images/web3-semantic.png', '', 'This is a decentralized content retrieval system in which users upload content - such as images and blogs - that can later be retrieved by other users using natural-language search (via queries or prompts). It was developed on Camp Network - a Layer-1 blockchain built to modernize intellectual property (IP) infrastructure and power the next generation of AI Agents on verifiable IP.', array['Engineering']::text[], 'Silas Osunba', '', 'https://github.com/TolaniSilas/web3-semantic-search', 'https://github.com/TolaniSilas/web3-semantic-search', '') on conflict (seed_key) do nothing;
insert into public.portfolio_projects (seed_key, title, position, published, image_url, image_path, description, categories, credit, date_label, link_url, code_url, demo_url) values ('project-5', 'Automatic Detection of Diabetic Retinopathy', 4, true, '/images/ai-as-a-doctor.png', '', 'An end-to-end AI-driven software system for early detection of Diabetic Retinopathy (DR) using deep learning and computer vision techniques. This project analyzes retinal fundus images to automate diagnosis, improving accuracy, speed, and accessibility of diabetic eye screening for ophthalmologists.', array['Engineering']::text[], 'Silas Osunba', '', 'https://diabetic-retinopathy-web.streamlit.app/', '', 'https://diabetic-retinopathy-web.streamlit.app/') on conflict (seed_key) do nothing;
insert into public.portfolio_projects (seed_key, title, position, published, image_url, image_path, description, categories, credit, date_label, link_url, code_url, demo_url) values ('project-6', 'Recipe Site Traffic', 5, true, '/images/recipe-traffic-image.png', '', 'An end-to-end ML system from problem formulation to model deployment via Docker; it also step forward to cover data drift and model monitoring. The product team at Tasty Bytes needs a data-driven assistance in the decision-making process for selecting which recipes to feature on the homepage so they can maximize high-traffic recipes and minimize low-traffic ones, with a target of correctly identifying popular recipes around 80% of the time, thereby boosting subscriptions.', array['Engineering']::text[], 'Silas Osunba', '', 'https://github.com/TolaniSilas/Recipe-Site-Traffic', 'https://github.com/TolaniSilas/Recipe-Site-Traffic', '') on conflict (seed_key) do nothing;
insert into public.portfolio_projects (seed_key, title, position, published, image_url, image_path, description, categories, credit, date_label, link_url, code_url, demo_url) values ('project-7', 'Loan Eligibility App', 6, true, '/images/loan-eligibility.png', '', 'A machine learning web application developed for Dream Housing Finance to automate real-time loan eligibility assessments. It analyzes customer data, validates financial metrics, and predicts approval outcomes with high accuracy, streamlining decision-making for the company.', array['Engineering']::text[], 'Silas Osunba', '', 'https://dreamhousingfinance.onrender.com/', '', 'https://dreamhousingfinance.onrender.com/') on conflict (seed_key) do nothing;
insert into public.portfolio_projects (seed_key, title, position, published, image_url, image_path, description, categories, credit, date_label, link_url, code_url, demo_url) values ('project-inspire-the-student', 'Inspire The Student Initiative', 7, true, '/images/affiliations/inspire-the-student.png', '', 'A student-led initiative supporting students through mentorship, accessible learning resources, and academic empowerment. Co-led 15 volunteers, shared over 750 study materials, and organized webinars reaching over 150 participants. The initiative was accepted into the Millennium Fellowship, supported by United Nations Academic Impact (UNAI) and the Millennium Campus Network (MCN).', array['Civic']::text[], 'Co-founded by Silas Osunba', '', 'https://www.linkedin.com/company/inspire-the-students', '', '') on conflict (seed_key) do nothing;
insert into public.portfolio_articles (seed_key, title, position, published, image_url, image_path, excerpt, date_value, reading_minutes, url) values ('article-1', 'Getting Started with LLMs: How to Serve LLM Applications as API Endpoints with FastAPI in Python', 0, true, '/images/llm-image.png', '', 'Large Language Models (LLMs) are leading advancements in Generative AI, revolutionizing how machines comprehend and produce human-like text. In this blog, we''ll explore how APIs short for Application Programming Interfaces, enable applications to harness the power of LLMs.', '2024-08-20', 12, 'https://medium.com/@tolanisilas3606/getting-started-with-llms-how-to-serve-llm-applications-as-api-endpoints-with-fastapi-in-python-af015399ef3e') on conflict (seed_key) do nothing;
